INSERT INTO bookstore_licenses ( type, url, is_commercial_allowed, is_derivative_allowed, requires_sharealike, requires_attribution ) SELECT p.license_type, p.license_url, CASE WHEN p.license_type IN ('CC_BY_NC', 'CC_BY_NC_SA', 'CC_BY_NC_ND') THEN 0 ELSE 1 END, CASE WHEN p.license_type IN ('CC_BY_ND', 'CC_BY_NC_ND') THEN 0 ELSE 1 END, CASE WHEN p.license_type IN ('CC_BY_SA', 'CC_BY_NC_SA') THEN 1 ELSE 0 END, CASE WHEN p.license_type IN ( 'CC_BY', 'CC_BY_SA', 'CC_BY_ND', 'CC_BY_NC', 'CC_BY_NC_SA', 'CC_BY_NC_ND' ) THEN 1 ELSE 0 END FROM ( SELECT DISTINCT license_type, license_url FROM bookstore_products ) p;
UPDATE bookstore_products SET delivery_mode = CASE WHEN fulfillment_type = 'LINK_ONLY' THEN 'LINK_ONLY' WHEN fulfillment_type = 'FILE_DOWNLOAD' THEN 'FILE_DOWNLOAD' ELSE delivery_mode END WHERE delivery_mode IS NULL;
UPDATE bookstore_suppliers SET supplier_type = 'POD_PRINTER' WHERE supplier_type = 'POD';
