INSERT INTO library_resources ( title, description, content_type, subject, grade_band, topic_tags, author, publisher, published_year, language, access_type, resource_url, file_type, metadata_json ) VALUES ( 'How Compound Interest Works', 'A plain-language explainer on compound interest, the Rule of 72, and why starting early matters for long-term wealth building.', 'article', 'Mathematics', 'senior', '["compound interest", "finance", "mathematics", "grade 10", "grade 11"]', 'Khan Academy', 'Khan Academy', 2023, 'en', 'free', 'https://www.khanacademy.org/economics-finance-domain/core-finance/interest-tutorial/compound-interest-tutorial/a/compound-interest-basics', 'link', '{}' ), ( 'Understanding Supply and Demand', 'Core microeconomics explainer covering demand and supply curves, equilibrium price, and market forces — aligned to Grade 10–12 Economics.', 'article', 'Economics', 'fet', '["supply", "demand", "equilibrium", "microeconomics", "grade 10", "grade 11", "grade 12"]', 'Investopedia', 'Investopedia', 2024, 'en', 'free', 'https://www.investopedia.com/terms/l/law-of-supply-demand.asp', 'link', '{}' ), ( 'DNA Replication Explained', 'Step-by-step breakdown of DNA replication: helicase, DNA polymerase, leading and lagging strands, and Okazaki fragments.', 'article', 'Life Sciences', 'fet', '["DNA", "replication", "genetics", "biology", "grade 12"]', 'Biology Online', 'Biology Online', 2023, 'en', 'free', 'https://www.biologyonline.com/tutorials/dna-replication', 'link', '{}' ), ( 'Everything Maths — Grade 12', 'Open textbook covering the full Grade 12 Mathematics curriculum: calculus, probability, statistics, algebra, and geometry. Free to download.', 'book', 'Mathematics', 'fet', '["mathematics", "grade 12", "calculus", "algebra", "probability", "open textbook"]', 'Siyavula', 'Siyavula Education', 2023, 'en', 'free', 'https://www.siyavula.com/read/maths/grade-12', 'link', '{}' ), ( 'Everything Science — Grade 11', 'Open textbook for Grade 11 Physical Sciences: mechanics, waves, electricity, matter and materials.', 'book', 'Physical Sciences', 'fet', '["physics", "chemistry", "grade 11", "mechanics", "waves", "electricity", "open textbook"]', 'Siyavula', 'Siyavula Education', 2023, 'en', 'free', 'https://www.siyavula.com/read/science/grade-11', 'link', '{}' ), ( 'Think Like a Computer Scientist — Python', 'Introductory programming textbook using Python. Covers variables, functions, loops, recursion, and object-oriented design. Suitable for university first-years and advanced FET learners.', 'book', 'Computer Science', 'university', '["python", "programming", "computer science", "algorithms", "open textbook"]', 'Allen B. Downey', 'Green Tea Press', 2015, 'en', 'free', 'https://greenteapress.com/thinkpython2/html/index.html', 'link', '{}' ), ( 'South African Journal of Education — Open Access', 'Peer-reviewed journal publishing research on education policy, curriculum, teaching practice, and learner outcomes in South Africa.', 'journal', 'Education', 'university', '["education research", "curriculum", "teaching", "south africa", "peer reviewed"]', 'SAJE Editorial Board', 'Education Association of South Africa', 2024, 'en', 'free', 'https://www.sajournalofeducation.co.za', 'link', '{}' ), ( 'African Journal of Mathematics, Science and Technology Education', 'Open-access journal focused on STEM education research across the African continent.', 'journal', 'Mathematics', 'university', '["STEM", "mathematics education", "science education", "Africa", "research"]', 'AMSTE Editorial Board', 'Routledge / Taylor & Francis', 2024, 'en', 'free', 'https://www.tandfonline.com/journals/rmse20', 'link', '{}' ), ( 'CAPS Curriculum Document — Mathematics Grades 10–12', 'Official DBE curriculum and assessment policy statement for Mathematics in the FET phase. Defines topics, weighting, and assessment guidelines.', 'publication', 'Mathematics', 'fet', '["CAPS", "curriculum", "assessment policy", "grade 10", "grade 11", "grade 12", "DBE"]', 'Department of Basic Education', 'Department of Basic Education', 2011, 'en', 'free', 'https://www.education.gov.za/Curriculum/CurriculumAssessmentPolicyStatements(CAPS)/CAPSFETMathematics.aspx', 'link', '{}' ), ( 'National Senior Certificate Examination Guidelines 2025', 'Official DBE examination guidelines covering subject content, question paper formats, and assessment criteria for NSC examinations.', 'publication', NULL, 'fet', '["NSC", "matric", "examination", "DBE", "grade 12", "assessment"]', 'Department of Basic Education', 'Department of Basic Education', 2024, 'en', 'free', 'https://www.education.gov.za/Curriculum/NationalSeniorCertificate(NSC)Examinations.aspx', 'link', '{}' ), ( 'Grade 12 Mathematics Paper 1 — 2023 NSC', 'Official 2023 National Senior Certificate Mathematics Paper 1 examination. Covers algebra, functions, finance, calculus, probability.', 'past_paper', 'Mathematics', 'fet', '["NSC", "grade 12", "mathematics", "paper 1", "2023", "exam"]', 'Department of Basic Education', 'Department of Basic Education', 2023, 'en', 'free', 'https://www.education.gov.za/Curriculum/NationalSeniorCertificate(NSC)Examinations/NSCPastExaminationpapers.aspx', 'link', '{}' ), ( 'Grade 12 Physical Sciences Paper 2 — 2023 NSC', 'Official 2023 NSC Physical Sciences Paper 2 (Chemistry). Covers organic chemistry, electrochemistry, and quantitative aspects of chemical change.', 'past_paper', 'Physical Sciences', 'fet', '["NSC", "grade 12", "physical sciences", "chemistry", "paper 2", "2023", "exam"]', 'Department of Basic Education', 'Department of Basic Education', 2023, 'en', 'free', 'https://www.education.gov.za/Curriculum/NationalSeniorCertificate(NSC)Examinations/NSCPastExaminationpapers.aspx', 'link', '{}' ), ( 'Quadratic Equations — Full Lesson', 'Video lesson covering factoring, completing the square, the quadratic formula, and graphing parabolas. Suitable for Grade 10–11 learners.', 'video_lesson', 'Mathematics', 'senior', '["quadratic equations", "grade 10", "grade 11", "algebra", "factoring", "parabola"]', 'Khan Academy', 'Khan Academy', 2023, 'en', 'free', 'https://www.youtube.com/watch?v=rJH0sMQMl2I', 'link', '{}' ), ( 'Introduction to Macroeconomics — University Lecture', 'Introductory university-level macroeconomics lecture covering GDP, inflation, unemployment, fiscal policy, and monetary policy.', 'video_lesson', 'Economics', 'university', '["macroeconomics", "GDP", "inflation", "fiscal policy", "monetary policy", "university", "first year"]', 'MIT OpenCourseWare', 'MIT', 2022, 'en', 'free', 'https://ocw.mit.edu/courses/14-01-principles-of-microeconomics-fall-2018/video-galleries/', 'link', '{}' ), ( 'Newton''s Laws of Motion — Grade 11 Physics', 'Video series covering Newton''s three laws with worked examples, free-body diagrams, and problem-solving techniques for Grade 11 Physical Sciences.', 'video_lesson', 'Physical Sciences', 'fet', '["Newton''s laws", "physics", "grade 11", "mechanics", "free body diagram", "forces"]', 'Mindset Learn', 'Mindset Network', 2022, 'en', 'free', 'https://www.youtube.com/playlist?list=PLBFdOuiNkGMHHxIDrFBDPzFbJDnmDKQoH', 'link', '{}' ) ON CONFLICT DO NOTHING;
INSERT INTO research_studies ( code, title, description, status, ethics_ref, principal_investigator, current_consent_version, current_stimulus_version, min_age, config, opened_at ) VALUES ( 'observational-silence-v1', 'Observational Silence: Selective Attention & Inattentional Blindness', 'Replication of the Simons & Chabris (1999) visual selective attention paradigm.', 'recruiting', 'NWU-00124-2026', 'Mondli Manzi (NWU Psychology)', 'v1', 'v1', 18, '{"study": "observational-silence-v1", "purposes": ["academic_research"]}', (strftime('%Y-%m-%dT%H:%M:%fZ','now')) ) ON CONFLICT (code) DO UPDATE SET status = 'recruiting', min_age = EXCLUDED.min_age;
UPDATE users SET trial_started_at = COALESCE(trial_started_at, (strftime('%Y-%m-%dT%H:%M:%fZ','now'))), trial_ends_at = COALESCE(trial_ends_at, (strftime('%Y-%m-%dT%H:%M:%fZ','now','+14 day'))), plan_type = COALESCE(plan_type, 'trial'), plan_status = COALESCE(plan_status, 'trialing') WHERE plan_status = 'trialing' AND (trial_ends_at IS NULL OR trial_started_at IS NULL);
INSERT INTO bookstore_products ( id, slug, title, description, phase, grade_min, grade_max, subjects, format, price_cents, currency, license_type, source_provider, fulfillment_type, file_type, vat_inclusive, tags, metadata_json, is_active, created_at, updated_at ) VALUES ( (lower(hex(randomblob(16)))), 'becoming-el-matador', 'Becoming El Matador', 'The English edition of Moloti Ditshego''s definitive guide to financial markets — from instruments and pricing mechanics to trading psychology and portfolio strategy. Written for serious students of markets who want to move beyond theory into real trading fluency and become the matador of their own financial future.', 'FOUNDATION', 0, 12, '["Financial Markets", "Economics", "Finance", "Investing"]', 'DIGITAL', 124900, 'ZAR', 'ALL_RIGHTS_RESERVED', 'MANUAL', 'FILE_DOWNLOAD', 'PDF', 1, '["financial-markets", "trading", "featured", "moloti-ditshego"]', '{"author": "Moloti Ditshego", "edition": "English Edition", "featured": true, "category": "Financial Markets", "coverUrl": "/images/books/becoming-el-matador-cover.jpg"}', 1, (strftime('%Y-%m-%dT%H:%M:%fZ','now')), (strftime('%Y-%m-%dT%H:%M:%fZ','now')) ) ON CONFLICT (slug) DO NOTHING;
INSERT INTO store_vendors (slug, name, tagline, description, accent, badge, icon_key, config_json, is_active, sort_order) VALUES ( 'clothing', 'Mr J Msibi', 'Wear the brand', 'Clothing, apparel, and accessories from Mr J Msibi — designed on the Ditshego house palette and built for the student who wears the story.', '#C9A24B', 'Campus threads', 'shirt', '{"paymentProvider":"stub","quoteOnly":false,"fulfillment":"SHIP_FROM_SUPPLIER"}', 1, 20 ), ( 'cosmetics', 'Cosmetics Store', 'Glow on campus', 'Skincare, body care, and fragrance routines crafted for the student lifestyle. Non-comedogenic, cruelty-free, and built for early classes and late sessions.', '#F9A8D4', 'Skincare & self-care', 'cosmetics', '{"paymentProvider":"stub","quoteOnly":false,"fulfillment":"SHIP_FROM_SUPPLIER"}', 1, 30 ), ( 'courses', 'Course Store', 'Buy the knowledge', 'Structured study courses and material packs — revision bundles, exam prep, and skills for the academic year. Every pack is CAPS-aligned and updated each term.', '#67E8F9', 'Study material', 'courses', '{"paymentProvider":"stub","quoteOnly":false,"fulfillment":"LINK_ONLY"}', 1, 40 ) ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, tagline = EXCLUDED.tagline, description = EXCLUDED.description, accent = EXCLUDED.accent, badge = EXCLUDED.badge, icon_key = EXCLUDED.icon_key, config_json = EXCLUDED.config_json, is_active = EXCLUDED.is_active, sort_order = EXCLUDED.sort_order, updated_at = (strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT INTO store_vendors (slug, name, tagline, description, accent, badge, icon_key, config_json, is_active, sort_order) VALUES ( 'school-academic-supplies', 'SCHOOL Academic Supplies', 'Premium academic essentials, delivered', 'The SCHOOL marketplace core: exercise books, calculators, maths sets, study guides, planners, past-paper bundles and the back-to-school stationery kit — CAPS-aligned, premium-gated, shipped nationwide. Plus the Cederberg Rooibos borderless pilot (DDP).', '#F2A900', 'Premium academic essentials', 'academic', '{"paymentProvider":"stub","quoteOnly":false,"fulfillment":"DROPSHIP"}', 1, 10 ) ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, tagline = EXCLUDED.tagline, description = EXCLUDED.description, accent = EXCLUDED.accent, badge = EXCLUDED.badge, icon_key = EXCLUDED.icon_key, config_json = EXCLUDED.config_json, is_active = EXCLUDED.is_active, sort_order = EXCLUDED.sort_order, updated_at = (strftime('%Y-%m-%dT%H:%M:%fZ','now'));
