INSERT INTO store_vendors (slug, name, tagline, description, accent, badge, icon_key, config_json, is_active, sort_order) VALUES ( 'cosmic-cottons', 'Cosmic Cottons', 'Threads from another orbit', 'Cosmic Cottons is a Ditshego Group clothing brand co-founded with Justin Msibi — a soft-palette, street-meets-sky aesthetic built for the student who wears the stars. Distinct positioning from Flightmode, and each drop is co-produced and sold on the SCHOOL marketplace.', '#A78BFA', 'Cosmic threads', 'shirt', '{"paymentProvider":"stub","quoteOnly":false,"fulfillment":"SHIP_FROM_SUPPLIER"}', 1, 21 ), ( 'flightmode', 'Flightmode', 'Wear the altitude', 'Flightmode is a Ditshego Group clothing brand co-founded with Kopano Ditshego — a high-energy, aviation-inspired streetwear line for a different demographic than Cosmic Cottons, so the two brands never cannibalise each other. Co-produced and sold on the SCHOOL marketplace.', '#38BDF8', 'Flight gear', 'shirt', '{"paymentProvider":"stub","quoteOnly":false,"fulfillment":"SHIP_FROM_SUPPLIER"}', 1, 22 ) ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, tagline = EXCLUDED.tagline, description = EXCLUDED.description, accent = EXCLUDED.accent, badge = EXCLUDED.badge, icon_key = EXCLUDED.icon_key, config_json = EXCLUDED.config_json, is_active = EXCLUDED.is_active, sort_order = EXCLUDED.sort_order, updated_at = (strftime('%Y-%m-%dT%H:%M:%fZ','now'));
